stopifnot({x<-rawToChar(as.raw(c(65,0,233)),multiple=TRUE);identical(lapply(x,charToRaw),list(as.raw(65),raw(),as.raw(233))) && identical(Encoding(x),rep("unknown",3L))})
stopifnot(identical(rawToChar(raw(),multiple=TRUE),character()))
stopifnot(identical(rawToChar(as.raw(c(65,0,0))),"A"))
stopifnot(identical(rawToChar(as.raw(c(0,0))),""))
stopifnot({x<-rawToChar(as.raw(c(195,169)));identical(Encoding(x),"unknown") && identical(charToRaw(x),as.raw(c(195,169)))})
stopifnot({e<-tryCatch(rawToChar(as.raw(c(65,0,66))),error=function(e)conditionMessage(e));grepl("^embedded nul in string",e,useBytes=TRUE)})
stopifnot(identical(tryCatch(rawToChar(as.raw(65),multiple=NA),error=function(e)conditionMessage(e)),"argument \'multiple\' must be TRUE or FALSE"))
stopifnot(identical(tryCatch(rawToChar(as.raw(65),multiple=logical()),error=function(e)conditionMessage(e)),"argument \'multiple\' must be TRUE or FALSE"))
stopifnot(identical(tryCatch(rawToChar(1L),error=function(e)conditionMessage(e)),"argument \'x\' must be a raw vector"))
stopifnot({x<-as.raw(c(65,66));names(x)<-c("a","b");identical(rawToChar(x),"AB")})
stopifnot({x<-rawToChar(as.raw(255));identical(charToRaw(x),as.raw(255)) && identical(Encoding(x),"unknown")})
stopifnot(identical(tryCatch(rawToChar(as.raw(c(65,0,66))),error=function(e)conditionMessage(e)),"embedded nul in string: 'A\\0B'"))
stopifnot(identical(rawToChar(as.raw(c(65,66)),multiple=2L),c("A","B")))
stopifnot({x<-rawToChar(as.raw(c(195,169)),multiple=TRUE);identical(lapply(x,charToRaw),list(as.raw(195),as.raw(169))) && identical(Encoding(x),c("unknown","unknown"))})
stopifnot(identical(rawToChar(multiple=TRUE,x=as.raw(c(65,66))),c("A","B")))
TRUE
